-- Clock values are compared through invariants so the two processes can run at different instants.
SELECT CURRENT_DATE=CURDATE() AS d,LOCALTIME(9)=CURTIME(9) AS t,LOCALTIMESTAMP(9)=NOW(9) AS ts;
SELECT LOCALTIME(9)=CAST(LOCALTIMESTAMP(9) AS TIME(9)) AS t,CURRENT_DATE=CAST(LOCALTIMESTAMP(9) AS DATE) AS d;
SELECT CAST(TIME '12:00:00.123456789' AS TIMESTAMP(9))=CAST(CURRENT_DATE AS TIMESTAMP)+TIME '12:00:00.123456789' AS v;
SELECT CAST(CAST(TIME '12:00:00' AS TIMESTAMP) AS DATE)=CURRENT_DATE AS v;
SELECT COALESCE(TIME '12:00:00',LOCALTIMESTAMP(9))=CAST(CURRENT_DATE AS TIMESTAMP)+TIME '12:00:00' AS v;
SELECT CASE WHEN CURRENT_DATE=CURDATE() THEN TIME '12:00:00' ELSE LOCALTIMESTAMP(9) END=CAST(CURRENT_DATE AS TIMESTAMP)+TIME '12:00:00' AS v;
SELECT CURRENT_DATE(1);
SELECT LOCALTIME(-1);
SELECT LOCALTIME(10);
SELECT NOW(10);
SELECT CURDATE;
SELECT (CURRENT_DATE-TIME '12:00:00') MONTH AS v;
SELECT (TIME '12:00:00'-CURRENT_DATE) MONTH AS v;
SELECT (TIME '12:00:00'-TIME '11:00:00') YEAR TO MONTH AS v;
WITH x AS (SELECT CAST(TIME '12:00:00' AS TIMESTAMP) AS ts) SELECT ts=(SELECT CAST(CURRENT_DATE AS TIMESTAMP)+TIME '12:00:00') AS v FROM x;
SELECT COUNT(*) AS n FROM (SELECT TIME '12:00:00' AS v UNION SELECT CAST(CURRENT_DATE AS TIMESTAMP)+TIME '12:00:00') x;
SELECT ROW(CAST(TIME '12:00:00' AS TIMESTAMP)=CAST(CURRENT_DATE AS TIMESTAMP)+TIME '12:00:00',1) AS v;
CREATE TABLE clock_values(id INT PRIMARY KEY,d DATE DEFAULT CURRENT_DATE,t TIME(9) DEFAULT LOCALTIME(9),ts TIMESTAMP(9) DEFAULT LOCALTIMESTAMP(9),promoted TIMESTAMP DEFAULT CAST(TIME '12:00:00' AS TIMESTAMP));
BEGIN;
INSERT INTO clock_values(id) VALUES(1),(2);
SELECT id,d=CURRENT_DATE AS d,t=LOCALTIME(9) AS t,ts=LOCALTIMESTAMP(9) AS ts,promoted=CAST(CURRENT_DATE AS TIMESTAMP)+TIME '12:00:00' AS p FROM clock_values ORDER BY id;
SAVEPOINT keep_clock;
UPDATE clock_values SET ts=NOW(9);
ROLLBACK TO SAVEPOINT keep_clock;
SELECT ts=LOCALTIMESTAMP(9) AS v FROM clock_values ORDER BY id;
ROLLBACK;
SELECT COUNT(*) AS n FROM clock_values;
INSERT INTO clock_values(id,d,t,ts,promoted) SELECT 1,CURRENT_DATE,LOCALTIME(9),LOCALTIMESTAMP(9),TIME '12:00:00';
SELECT d=CAST(ts AS DATE) AS d,t=CAST(ts AS TIME(9)) AS t,promoted=CAST(d AS TIMESTAMP)+TIME '12:00:00' AS p FROM clock_values;
CREATE TABLE dynamic_clock(d DATE DEFAULT (SELECT CURRENT_DATE),ts TIMESTAMP DEFAULT DATE_TRUNC(DAY,CAST(TIME '12:00:00' AS TIMESTAMP)));
INSERT INTO dynamic_clock DEFAULT VALUES;
SELECT d=CURRENT_DATE AS d,ts=CAST(d AS TIMESTAMP) AS ts FROM dynamic_clock;
UPDATE clock_values SET promoted=TIME '13:00:00';
SELECT promoted=CAST(d AS TIMESTAMP)+TIME '13:00:00' AS v FROM clock_values;
DROP TABLE clock_values,dynamic_clock;
